import type { SubjectId } from "@/lib/types";
import raw from "./memoryTricks.json";

/**
 * Memory Trick PDFs shown on each subject's "Memory Tricks" tab. Seed records are
 * generated by scripts/build-memory-tricks.py; the admin side will add, edit and
 * upload more (see docs/ADMIN_PLAN.md), so the client reads them through
 * `useMemoryTricks` in lib/content.ts rather than importing this list directly.
 */
export interface MemoryTrick {
  id: string;
  title: string;
  subject: SubjectId;
  /** Sub-subject (one of the subject's systems). `null` = applies to the whole subject ("General"). */
  system: string | null;
  /** One-line hook shown under the title, e.g. "VEAL CHOP". */
  description: string;
  access: "free" | "premium";
  status: "draft" | "published" | "archived";
  /** Sort order inside its subject/system group. */
  order: number;
  file: { url: string; name: string; pages: number; sizeKb: number };
  updatedAt: string;
}

export const MEMORY_TRICKS_SEED = raw as MemoryTrick[];

export const GENERAL = "General";
